      "achados": [
        {
          "proposicao": "A fonte reúne arranjos de plantas com separadores trifásicos e bifásicos em diferentes estágios de pressão, tratamento eletrostático, compressão e tratamento de água produzida, indicando interfaces relevantes do separador com gás e água.",
          "trechos": [
            "Ef431b40fd46fa274:0:699",
            "Ef431b40fd46fa274:699:1392",
            "Ef431b40fd46fa274:2092:2529"
