          ],
          "limites": [
            "o trecho é predominantemente enumerativo e não explicita mecanismos, critérios de seleção ou lógica de proteção",
            "não traz detalhes sobre partidas, paradas, ESD, PSV ou inspeção do vaso"
          ]
        },
        {
          "proposicao": "O uso de produtos químicos como desemulsificantes, antiespumantes, inibidores de incrustação, inibidores de corrosão e polieletrólitos aparece associado ao processamento primário e ao tratamento subsequente.",
          "trechos": [
            "Ef431b40fd46fa274:1392:2092"
          ],
          "condicoes": [
            "plantas com separação óleo-gás-água e tratamento do óleo/água"
          ],
          "limites": [
            "não há dosagens, critérios de aplicação, compatibilidades nem consequências operacionais detalhadas",
            "a mera listagem não permite inferir obrigatoriedade ou efetividade"
          ]
        }
      ]
    },
    {
      "id": "E0e4cbfd587b92329",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O separador trifásico é descrito como elemento capaz de absorver flutuações do processo de separação quando há alterações frequentes na vazão de produção de petróleo.",
          "trechos": [
            "E0e4cbfd587b92329:0:699"
          ],
          "condicoes": [
            "ocorrência de alterações frequentes na vazão de produção",
            "contexto de processo de separação trifásica"
          ],
          "limites": [
            "o trecho é breve e não informa como essa absorção é obtida em termos de controle, volume útil ou tempo de residência",
            "não estabelece limites de transiente nem desempenho garantido"
          ]
        }
      ]
    },
    {
      "id": "E11dd0a6b5d3c16ec",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "Para vasos separadores, trocadores de calor e tratadores, o regulamento exige descrever características funcionais e dimensionais como volume, pressão de projeto, pressão de operação ou pressão máxima de operação, PMTA, temperaturas de operação, vazão operacional e pressão de ajuste das PSVs.",
          "trechos": [
            "E11dd0a6b5d3c16ec:0:700"
          ],
          "condicoes": [
            "instalações terrestres de produção de petróleo e gás natural abrangidas pelo RTSGI"
          ],
          "limites": [
            "a fonte é norma para instalações terrestres, não requisito automaticamente transferível para FPSO",
            "o trecho trata de documentação e descrição, não de critérios de dimensionamento ou ajuste"
          ]
        },
        {
          "proposicao": "O regulamento requer descrever o sistema de automação, monitoramento, controle e parada de emergência das principais operações, com ênfase nas relevantes para segurança e continuidade operacional.",
          "trechos": [
            "E11dd0a6b5d3c16ec:700:1400",
            "E11dd0a6b5d3c16ec:1400:2096"
          ],
          "condicoes": [
            "instalações terrestres enquadradas no regulamento",
            "operações principais da instalação"
          ],
          "limites": [
            "não detalha arquitetura de ESD, lógica de intertravamento nem setpoints",
            "não deve ser lido como procedimento operacional específico para separadores em FPSOs"
          ]
        },
        {
          "proposicao": "O regulamento também exige disponibilizar fluxogramas de processo com localização e identificação de equipamentos, tubulações e acessórios, identificando correntes de óleo, gás e água.",
          "trechos": [
            "E11dd0a6b5d3c16ec:1400:2096",
            "E11dd0a6b5d3c16ec:2096:2143"
          ],
          "condicoes": [
            "documentação da instalação abrangida"
          ],
          "limites": [
            "o trecho não define nível de detalhamento de malhas de controle ou interfaces internas do vaso além da identificação de correntes",
            "escopo normativo restrito a instalações terrestres"
          ]
        }
      ]
    },
    {
      "id": "E77983e5d824ece2c",
