      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "No vaso separador descrito, instrumentos de controle enviam sinais para a sala de controle para monitoramento contínuo de variáveis como pressão e fluxo.",
          "trechos": [
            "E77983e5d824ece2c:0:694"
          ],
          "condicoes": [
            "arranjo instrumental do vaso separador analisado"
          ],
          "limites": [
